WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_esc_two'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '双人扶梯比较', 'kp-trv-esc-two', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "双人扶梯比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "甲和乙都在同一部电梯上走，但速度不同，导致的各自走的级数也不同。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲乙两人在同一扶梯上向上走。甲每秒走 2 级，到达顶部走了 40 级；乙每秒走 3 级，到达顶部走了 45 级。求扶梯共有多少级？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "无论是谁走，这部扶梯的【总级数 S】是固定不变的！而且电梯的速度 V梯 也是不变的。"}]}, {"type": "katexBlock", "attrs": {"content": "S = N_{甲} + V_{梯} \\times \\frac{N_{甲}}{V_{甲}} \\quad ; \\quad S = N_{乙} + V_{梯} \\times \\frac{N_{乙}}{V_{乙}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 如上题数据。甲用时 = 40/2 = 20秒。乙用时 = 45/3 = 15秒。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "等式联立：40 + V梯×20 = 45 + V梯×15。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "解 V梯：5 × V梯 = 5。所以 V梯 = 1 级/秒。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求总级数 S：S = 40 + 1×20 = 60 级。"}]}]}]}]}$$ AS jsonb), NULL, '双人扶梯比较的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "双人扶梯比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_esc_two", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
